from decimal import Decimal
from typing import Any


def _value(image: dict | None, column: str) -> Any:
    if image is None:
        return ""
    value = image.get(column, "")
    return "" if value is None else value


def _nvl(value: Any, default: Any) -> Any:
    return default if value is None or value == "" else value


def _number(value: Any) -> Decimal:
    value = _nvl(value, 0)
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _date_gte(left: Any, right: Any) -> bool:
    left_text = str(left)
    right_text = str(right)
    if left_text == "00000000" or right_text == "00000000":
        return False
    return left_text >= right_text


def _error(code: str, message: str, severity: str = "BLOCK") -> dict:
    return {
        "code": code,
        "message": message,
        "severity": severity,
    }


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    errors: list[dict] = []

    if event not in ("INSERT", "UPDATE"):
        return errors

    amount = _number(_nvl(_value(record, "AMT"), 0))
    status = _value(record, "STAT_CD")
    lost_reason = _value(record, "LOST_RSN")
    close_date = _value(record, "CLOSE_DT")
    stage_percent = _number(_value(record, "STAGE_PCT"))

    # OPP-001
    if not amount >= Decimal("0"):
        errors.append(_error("E3001", "Amount negative"))

    # OPP-002
    if status == "W" and amount == Decimal("0"):
        errors.append(_error("E3002", "Won opportunity requires amount"))

    # OPP-003
    if status == "L" and lost_reason == "":
        errors.append(_error("E3003", "Lost reason required"))

    # OPP-004
    if status == "W" and close_date == "00000000":
        errors.append(_error("E3004", "Won opportunity requires close date"))

    # OPP-005
    if event == "UPDATE":
        old_status = _value(old, "STAT_CD")
        if old_status == "W" and status != "W":
            errors.append(_error("E3005", "Cannot reopen a won opportunity"))

    # OPP-006
    stage_is_valid = (
        (status == "P" and stage_percent == Decimal("10"))
        or (status == "Q" and stage_percent == Decimal("25"))
        or (status == "N" and stage_percent == Decimal("60"))
        or (status == "W" and stage_percent == Decimal("100"))
        or (status == "L" and stage_percent == Decimal("0"))
    )
    if not stage_is_valid:
        errors.append(_error("E3006", "Stage percent inconsistent with status"))

    # OPP-007
    if event == "INSERT":
        close_date_is_valid = (
            close_date == "00000000"
            or _date_gte(close_date, today)
        )
        if not close_date_is_valid:
            errors.append(
                _error("E3007", "Close date in past", severity="WARN")
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
